function starterOf(t){return (TOOL_INTRO[t.id]||{}).starter||STARTERS[t.id]||(t.intro&&t.intro.starter)||null;}
function starterBlock(hub,t){const st=starterOf(t);if(!st)return null;const S=App.state.obPick=App.state.obPick||{},key=pinKey(hub,t.id),sel=S[key]=S[key]||[];
  return Card({cls:'ob-card'},el('b',{style:'font-weight:500'},st.q),el('div',{class:'ob-row'},st.opts.map(([n])=>{const on=sel.includes(n);return el('button',{class:'ob-pill'+(on?' on':''),style:'padding:0 var(--s4)','aria-pressed':String(on),onclick:()=>{const i=sel.indexOf(n);if(i>=0)sel.splice(i,1);else sel.push(n);App.refresh();}},n);})),st.note?el('small',{class:'muted'},st.note):null);}
function starterMake(hub,t){const st=starterOf(t),S=App.state.obPick||{},key=pinKey(hub,t.id),sel=(S[key]||[]);if(!st||!sel.length)return 0;const tk2=todayK();let i=0;const made=[];
  st.opts.filter(([n])=>sel.includes(n)).forEach(([n,patch])=>{const f=fieldDefaults(t.fields,Object.assign({what:n},patch||{}));if(st.stagger&&+f.every){const due=addK(tk2,1+(i%Math.max(1,+f.every)));f.last=addK(due,-(+f.every));}made.push(create('entry',{hub,tool:t.id,f}));i++;});
  delete S[key];return made.length;}

/* ---------- quick log from capture ---------- */
const guessCat=w=>{const l=w.toLowerCase();if(/lunch|dinner|breakfast|coffee|latte|starbucks|dunkin|tim hortons|chipotle|mcdonald|doordash|grubhub|uber ?eats|restaurant|takeout|pizza|burger|drinks|bar\b|brunch|sushi/.test(l))return'Dining out';if(/grocer|market|costco|aldi|wegmans|trader/.test(l))return'Groceries';if(/gas|fuel|uber|lyft|bus|train|parking|toll|metro|taxi/.test(l))return'Gas & transit';if(/movie|concert|game|tickets|bowling/.test(l))return'Fun';if(/haircut|salon|nails|gym|pharmacy/.test(l))return'Personal';if(/amazon|target|clothes|shoes|shirt/.test(l))return'Shopping';if(/hotel|flight|airbnb/.test(l))return'Travel';if(/soap|paper towels|cleaning|detergent|light ?bulb/.test(l))return'Household';return'Other';};
const qlAdd=(hub,tool,f)=>{const r=create('entry',{hub,tool,f});return()=>remove(r.id,{silent:true,hard:true});};
const QL=[
 {re:/^walked\s+([A-Z][a-z]+)(?:\s+(?:for\s+)?(\d+)\s*(?:min|mins|minutes|m))?$/,ok:()=>toolOn('Pets','walks'),label:m=>`Log a walk with ${m[1]}${m[2]?`, ${m[2]} min`:''}`,run:m=>qlAdd('Pets','walks',{what:`Walk with ${m[1]}`,n:m[2]?+m[2]:'',note:'',date:todayK()}),toast:'Walk logged'},
 {re:/^(?:spent|paid)\s+\$?(\d+(?:\.\d{1,2})?)\s+(?:on|for|at)\s+(.+)$/i,label:m=>`Log ${money(+m[1])} on ${m[2]}`,run:m=>qlAdd('Finances','spending',{what:capW(m[2]),amount:+m[1],cat:guessCat(m[2]),date:todayK()}),toast:'Expense logged'},
 {re:/^slept\s+(\d+(?:\.\d)?)\s*(?:h|hr|hrs|hours?)\b/i,label:m=>`Log ${m[1]} hours of sleep`,run:m=>{const x=ofType('Health','checkin','').find(c=>c.f.date===todayK());if(x){const was=x.f.sleep;x.f.sleep=+m[1];put(x);return()=>{x.f.sleep=was;put(x);};}return qlAdd('Health','checkin',{e:'OK',water:0,sleep:+m[1],note:'',date:todayK()});},toast:'Sleep logged'},
 {re:/^(ran|jogged|walked|biked|cycled|swam|hiked|rowed|lifted|did yoga|yoga|stretched|worked out|played \w+)\b(?:\s+(?:for\s+)?(\d+(?:\.\d+)?)\s*(min|mins|minutes|m|mi|miles|km|k)\b)?(?:\s+(?:in\s+|for\s+)?(\d+)\s*(?:min|mins|minutes|m)\b)?/i,label:m=>{const w=m[1].toLowerCase();return `Log a workout · ${capW(w)}${m[2]?` ${m[2]} ${m[3]}`:''}${m[4]?` in ${m[4]} min`:''}`;},run:m=>{const dist=m[3]&&/^(mi|miles|km|k)$/i.test(m[3]),min=dist?(m[4]?+m[4]:30):(m[2]?+m[2]:30),what={ran:'Run',jogged:'Run',walked:'Walk',biked:'Bike ride',cycled:'Bike ride',swam:'Swim',hiked:'Hike',rowed:'Row',lifted:'Strength',yoga:'Yoga','did yoga':'Yoga',stretched:'Stretching','worked out':'Workout'}[m[1].toLowerCase()]||capW(m[1].replace(/^played /i,''));return qlAdd('Health','workouts',{what,min,miles:dist?+m[2]:'',feel:'Steady',date:todayK()});},toast:'Workout logged'},
 {re:/^read\s+(\d+)\s+pages?\b/i,ok:()=>ofType('Learning','reading','').some(x=>x.f.status==='Reading'),label:m=>{const b=ofType('Learning','reading','').find(x=>x.f.status==='Reading');return `Log ${m[1]} pages of ${b.f.what}`;},run:m=>{const b=ofType('Learning','reading','').find(x=>x.f.status==='Reading'),c=clone(b.f),n=+m[1],dk=todayK();b.f.page=Math.min(+b.f.pages||9e9,(+b.f.page||0)+n);b.f.log=Object.assign({},b.f.log,{[dk]:(+(b.f.log||{})[dk]||0)+n});put(b);return()=>{b.f=c;put(b);};},toast:'Pages logged'},
 {re:/^(?:weighed|weigh|weight)\s+(\d+(?:\.\d)?)\s*(lb|lbs|kg)?$/i,label:m=>`Log weight · ${m[1]}${m[2]?' '+m[2]:''}`,run:m=>{let x=ofType('Health','measure','').find(q=>/weight/i.test(q.f.what||''));let made=null;if(!x){x=made=create('entry',{hub:'Health',tool:'measure',f:{what:'Weight',unit:m[2]||'lb',logs:[]}});}const c=clone(x.f);x.f.logs=[...(x.f.logs||[]),{date:todayK(),v:+m[1]}];put(x);return()=>{if(made)remove(made.id,{silent:true,hard:true});else{x.f=c;put(x);}};},toast:'Weight logged'},
 {re:/^volunteered\s+(\d+(?:\.\d)?)\s*(?:h|hrs?|hours?)\s*(?:at|with|for)?\s*(.*)$/i,ok:()=>toolOn('Community','volunteer'),label:m=>`Log ${m[1]} volunteer hours${m[2]?` at ${m[2]}`:''}`,run:m=>qlAdd('Community','volunteer',{what:capW(m[2]||'Volunteering'),n:+m[1],note:'',date:todayK()}),toast:'Hours logged'},
 {re:/^(?:donated|gave)\s+\$?(\d+(?:\.\d{1,2})?)\s+to\s+(.+)$/i,ok:()=>toolOn('Community','giving'),label:m=>`Log a ${money(+m[1])} gift to ${m[2]}`,run:m=>qlAdd('Community','giving',{what:capW(m[2]),n:+m[1],note:'',date:todayK()}),toast:'Gift logged'},
 {re:/^waiting (?:on|for)\s+([A-Z][\w.'-]*(?:\s[A-Z][\w.'-]*)?)\s+(?:for|to|about|on)\s+(.+)$/i,label:m=>`Waiting on ${m[1]} · ${m[2]}`,run:m=>{const r=create('wait',{title:capW(m[2]),who:m[1],since:todayK(),follow:addK(todayK(),3),notes:'',done:false});return()=>remove(r.id,{silent:true,hard:true});},toast:'Added to Waiting'},
];
function quickLog(text){const t=(text||'').trim().replace(/[.!]+$/,'');if(!t||t.length>90)return null;if(parseRepeat(t)&&!/^waiting/i.test(t))return null;for(const q of QL){const m=t.match(q.re);if(m&&(!q.ok||q.ok()))return{label:q.label(m),run:()=>{const undo=q.run(m);markGs('capture');toast(q.toast,()=>{undo&&undo();App.refresh();});App.refresh();}};}return null;}

/* one tap flips every module in an area; turning off deletes nothing, and it can be undone */
function setAllTools(a,ts,on){const was=ts.map(t=>[t.id,!!toolOn(a,t.id)]);ts.forEach(t=>{if(!!toolOn(a,t.id)!==on)setToolOn(a,t.id,on);});App.refresh();toast(on?`All ${a} modules on`:`All ${a} modules off`,()=>{was.forEach(([id,v])=>setToolOn(a,id,v));App.refresh();});}
